namespace sv_aab8dbb4331c4ff4b0ee72f1ccd0fbc0.Services;

public class AppointmentService
{
    private static readonly List<string> _doctors = new()
    {
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Williams",
        "Dr. Brown"
    };

    private static readonly Dictionary<string, List<string>> _timeSlots = new()
    {
        ["Dr. Smith"] = new() { "9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM" },
        ["Dr. Johnson"] = new() { "8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM" },
        ["Dr. Williams"] = new() { "9:00 AM", "10:30 AM", "11:30 AM", "2:30 PM" },
        ["Dr. Brown"] = new() { "8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM" }
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(_doctors);
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        if (_timeSlots.TryGetValue(doctor, out var slots))
        {
            return Task.FromResult(slots);
        }
        return Task.FromResult(new List<string>());
    }

    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Reject email with outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors["Email"] = "Account has outstanding balance";
        }

        // Reject "None" insurance with Dr. Smith (doesn't accept self-pay)
        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors["Doctor"] = "Selected doctor does not accept self-pay patients";
        }

        // Reject 10:00 AM as taken (simulates race condition)
        if (timeSlot == "10:00 AM")
        {
            errors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_aab8dbb4331c4ff4b0ee72f1ccd0fbc0.Services
@using System.ComponentModel.DataAnnotations
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm Model="@_model" OnValidSubmit="HandleSubmit" FormName="appointment">
    <DataAnnotationsValidator />

    @* STEP 1: Patient Information *@
    <fieldset>
        <legend>Step 1: Patient Information</legend>

        <div class="mb-3">
            <label for="patientName" class="form-label">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="_model.PatientName" />
            <ValidationMessage For="() => _model.PatientName" />
        </div>

        <div class="mb-3">
            <label for="email" class="form-label">Email</label>
            <InputText id="email" class="form-control" @bind-Value="_model.Email" />
            <ValidationMessage For="() => _model.Email" />
            @if (_serverErrors.ContainsKey("Email"))
            {
                <div class="validation-message">@_serverErrors["Email"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="phone" class="form-label">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="_model.Phone" />
            <ValidationMessage For="() => _model.Phone" />
        </div>

        <div class="mb-3">
            <label for="insurance" class="form-label">Insurance Provider</label>
            <InputSelect id="insurance" class="form-control" @bind-Value="_model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => _model.InsuranceProvider" />
        </div>

        @if (!_showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">Next</button>
        }
    </fieldset>

    @* STEP 2: Appointment Details *@
    @if (_showStep2)
    {
        <fieldset class="mt-4">
            <legend>Step 2: Appointment Details</legend>

            <div class="mb-3">
                <label for="doctor" class="form-label">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-control" @bind-Value="_model.Doctor" ValueChanged="OnDoctorChanged" ValueExpression="() => _model.Doctor">
                    <option value="">-- Select --</option>
                    @foreach (var doc in _doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => _model.Doctor" />
                @if (_serverErrors.ContainsKey("Doctor"))
                {
                    <div class="validation-message">@_serverErrors["Doctor"]</div>
                }
            </div>

            <div class="mb-3">
                <label for="date" class="form-label">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="_model.AppointmentDate" />
                <ValidationMessage For="() => _model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label for="timeSlot" class="form-label">Time Slot</label>
                <InputSelect id="timeSlot" class="form-control" @bind-Value="_model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in _timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => _model.TimeSlot" />
                @if (_serverErrors.ContainsKey("TimeSlot"))
                {
                    <div class="validation-message">@_serverErrors["TimeSlot"]</div>
                }
            </div>

            <div class="mb-3">
                <label for="reason" class="form-label">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="_model.ReasonForVisit" />
                <ValidationMessage For="() => _model.ReasonForVisit" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">Back</button>
            <button type="button" class="btn btn-primary" @onclick="CheckAvailability">Check Availability</button>
        </fieldset>
    }

    @if (_confirmed)
    {
        <div class="alert alert-success mt-4">
            Appointment booked successfully!
        </div>
    }
</EditForm>

@code {
    private AppointmentModel _model = new();
    private bool _showStep2;
    private bool _confirmed;
    private List<string> _doctors = new();
    private List<string> _timeSlots = new();
    private Dictionary<string, string> _serverErrors = new();
    private EditContext? _editContext;

    protected override async Task OnInitializedAsync()
    {
        _doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        _editContext = new EditContext(_model);
        _editContext.EnableDataAnnotationsValidation();

        if (ValidateStep1())
        {
            _showStep2 = true;
        }
    }

    private bool ValidateStep1()
    {
        var results = new List<ValidationResult>();
        var context = new ValidationContext(_model);
        Validator.TryValidateProperty(_model.PatientName, new ValidationContext(_model) { MemberName = nameof(_model.PatientName) }, results);
        Validator.TryValidateProperty(_model.Email, new ValidationContext(_model) { MemberName = nameof(_model.Email) }, results);
        Validator.TryValidateProperty(_model.Phone, new ValidationContext(_model) { MemberName = nameof(_model.Phone) }, results);
        Validator.TryValidateProperty(_model.InsuranceProvider, new ValidationContext(_model) { MemberName = nameof(_model.InsuranceProvider) }, results);

        return results.Count == 0;
    }

    private async Task OnDoctorChanged(string doctor)
    {
        _model.Doctor = doctor;
        _model.TimeSlot = string.Empty;
        _serverErrors.Remove("Doctor");
        _serverErrors.Remove("TimeSlot");

        if (!string.IsNullOrEmpty(doctor) && _model.AppointmentDate.HasValue)
        {
            _timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                doctor, DateOnly.FromDateTime(_model.AppointmentDate.Value));
        }
        else
        {
            _timeSlots = new();
        }
    }

    private async Task LoadTimeSlots()
    {
        if (!string.IsNullOrEmpty(_model.Doctor) && _model.AppointmentDate.HasValue)
        {
            _timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                _model.Doctor, DateOnly.FromDateTime(_model.AppointmentDate.Value));
        }
    }

    private async Task CheckAvailability()
    {
        _serverErrors.Clear();
        _confirmed = false;

        // Client-side validation for step 2
        var results = new List<ValidationResult>();
        Validator.TryValidateProperty(_model.Doctor, new ValidationContext(_model) { MemberName = nameof(_model.Doctor) }, results);
        Validator.TryValidateProperty(_model.AppointmentDate, new ValidationContext(_model) { MemberName = nameof(_model.AppointmentDate) }, results);
        Validator.TryValidateProperty(_model.TimeSlot, new ValidationContext(_model) { MemberName = nameof(_model.TimeSlot) }, results);
        Validator.TryValidateProperty(_model.ReasonForVisit, new ValidationContext(_model) { MemberName = nameof(_model.ReasonForVisit) }, results);

        if (results.Count > 0)
        {
            return;
        }

        // Validate date is in the future
        if (_model.AppointmentDate.HasValue && _model.AppointmentDate.Value.Date <= DateTime.Today)
        {
            _serverErrors["AppointmentDate"] = "Date must be in the future";
            return;
        }

        // Server-side validation
        _serverErrors = await AppointmentService.ValidatePatientAsync(
            _model.Email,
            _model.InsuranceProvider,
            _model.Doctor,
            _model.TimeSlot);

        if (_serverErrors.Count == 0)
        {
            _confirmed = true;
        }
    }

    private void BackToStep1()
    {
        _showStep2 = false;
        _serverErrors.Clear();
    }

    private void HandleSubmit()
    {
        // Form submitted via EditForm validation
    }

    public class AppointmentModel
    {
        [Required(ErrorMessage = "Patient name is required")]
        public string PatientName { get; set; } = string.Empty;

        [Required(ErrorMessage = "Email is required")]
        [EmailAddress(ErrorMessage = "Invalid email format")]
        public string Email { get; set; } = string.Empty;

        [Required(ErrorMessage = "Phone is required")]
        public string Phone { get; set; } = string.Empty;

        [Required(ErrorMessage = "Insurance provider is required")]
        public string InsuranceProvider { get; set; } = string.Empty;

        [Required(ErrorMessage = "Doctor is required")]
        public string Doctor { get; set; } = string.Empty;

        [Required(ErrorMessage = "Date is required")]
        [FutureDate(ErrorMessage = "Date must be in the future")]
        public DateTime? AppointmentDate { get; set; }

        [Required(ErrorMessage = "Time slot is required")]
        public string TimeSlot { get; set; } = string.Empty;

        [Required(ErrorMessage = "Reason for visit is required")]
        [MaxLength(500, ErrorMessage = "Reason must be 500 characters or less")]
        public string ReasonForVisit { get; set; } = string.Empty;
    }

    public class FutureDateAttribute : ValidationAttribute
    {
        protected override ValidationResult? IsValid(object? value, ValidationContext validationContext)
        {
            if (value is DateTime date && date.Date <= DateTime.Today)
            {
                return new ValidationResult(ErrorMessage);
            }
            return ValidationResult.Success;
        }
    }
}

