+            _timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
+                _model.Doctor, DateOnly.FromDateTime(_model.AppointmentDate.Value));
+        }
+    }
+
+    private async Task CheckAvailability()
+    {
+        _serverErrors.Clear();
+        _confirmed = false;
+
+        // Client-side validation for step 2
+        var results = new List<ValidationResult>();
+        Validator.TryValidateProperty(_model.Doctor, new ValidationContext(_model) { MemberName = nameof(_model.Doctor) }, results);
+        Validator.TryValidateProperty(_model.AppointmentDate, new ValidationContext(_model) { MemberName = nameof(_model.AppointmentDate) }, results);
+        Validator.TryValidateProperty(_model.TimeSlot, new ValidationContext(_model) { MemberName = nameof(_model.TimeSlot) }, results);
+        Validator.TryValidateProperty(_model.ReasonForVisit, new ValidationContext(_model) { MemberName = nameof(_model.ReasonForVisit) }, results);
+
+        if (results.Count > 0)
+        {
+            return;
+        }
+
+        // Validate date is in the future
+        if (_model.AppointmentDate.HasValue && _model.AppointmentDate.Value.Date <= DateTime.Today)
+        {
+            _serverErrors["AppointmentDate"] = "Date must be in the future";
+            return;
+        }
+
+        // Server-side validation
+        _serverErrors = await AppointmentService.ValidatePatientAsync(
+            _model.Email,
+            _model.InsuranceProvider,
+            _model.Doctor,
+            _model.TimeSlot);
+
+        if (_serverErrors.Count == 0)
+        {
+            _confirmed = true;
+        }
+    }
+
+    private void BackToStep1()
+    {
+        _showStep2 = false;
+        _serverErrors.Clear();
+    }
+
+    private void HandleSubmit()
+    {
+        // Form submitted via EditForm validation
+    }
+
+    public class AppointmentModel
+    {
+        [Required(ErrorMessage = "Patient name is required")]
+        public string PatientName { get; set; } = string.Empty;
+
+        [Required(ErrorMessage = "Email is required")]
+        [EmailAddress(ErrorMessage = "Invalid email format")]
+        public string Email { get; set; } = string.Empty;
+
+        [Required(ErrorMessage = "Phone is required")]
+        public string Phone { get; set; } = string.Empty;
+
+        [Required(ErrorMessage = "Insurance provider is required")]
+        public string InsuranceProvider { get; set; } = string.Empty;
+
+        [Required(ErrorMessage = "Doctor is required")]
+        public string Doctor { get; set; } = string.Empty;
+
+        [Required(ErrorMessage = "Date is required")]
+        [FutureDate(ErrorMessage = "Date must be in the future")]
+        public DateTime? AppointmentDate { get; set; }
+
+        [Required(ErrorMessage = "Time slot is required")]
+        public string TimeSlot { get; set; } = string.Empty;
+
+        [Required(ErrorMessage = "Reason for visit is required")]
+        [MaxLength(500, ErrorMessage = "Reason must be 500 characters or less")]
+        public string ReasonForVisit { get; set; } = string.Empty;
+    }
+
+    public class FutureDateAttribute : ValidationAttribute
+    {
+        protected override ValidationResult? IsValid(object? value, ValidationContext validationContext)
+        {
+            if (value is DateTime date && date.Date <= DateTime.Today)
+            {
+                return new ValidationResult(ErrorMessage);
+            }
+            return ValidationResult.Success;
+        }
+    }
+}
